import { test, expect } from '@playwright/test';

test.describe('Dynamic Content Updates Announcement', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dynamic-content');
  });

  test('should announce dynamic content updates using aria-live regions', async ({ page }) => {
    // Verify initial content is visible
    const initialContent = page.getByText('Initial content');
    await expect(initialContent).toBeVisible();

    // Verify aria-live region exists
    const liveRegion = page.locator('[aria-live="polite"]');
    await expect(liveRegion).toBeVisible();

    // Verify aria-live region has appropriate role
    await expect(liveRegion).toHaveAttribute('role', 'status');

    // Trigger dynamic content update
    const updateButton = page.getByRole('button', { name: /update content/i });
    await updateButton.click();

    // Wait for content update to complete
    await page.waitForTimeout(500);

    // Verify new content is displayed
    const updatedContent = page.getByText('Updated content');
    await expect(updatedContent).toBeVisible();

    // Verify old content is replaced
    await expect(initialContent).not.toBeVisible();

    // Verify live region content is updated
    await expect(liveRegion).toContainText('Content updated');

    // Verify screen reader announcement text is present
    const announcementText = page.getByText('Content updated');
    await expect(announcementText).toBeVisible();
  });

  test('should handle multiple dynamic updates and maintain announcement integrity', async ({ page }) => {
    // Trigger first update
    const updateButton = page.getByRole('button', { name: /update content/i });
    await updateButton.click();

    // Wait for first update
    await page.waitForTimeout(500);

    // Verify first update announcement
    const liveRegion = page.locator('[aria-live="polite"]');
    await expect(liveRegion).toContainText('Content updated');

    // Trigger second update
    await updateButton.click();

    // Wait for second update
    await page.waitForTimeout(500);

    // Verify second update announcement
    await expect(liveRegion).toContainText('Content updated');

    // Verify content reflects second update
    const secondContent = page.getByText('Second update');
    await expect(secondContent).toBeVisible();

    // Verify first update content is gone
    const firstContent = page.getByText('Initial content');
    await expect(firstContent).not.toBeVisible();

    // Verify live region does not contain both announcements
    const liveRegionText = await liveRegion.textContent();
    expect(liveRegionText).not.toContain('Content updated');
    expect(liveRegionText).toContain('Second update');
  });
});
